[FormControlEventHandler(formControlStr(TAMRebateDealNewDeal, TAMRebateDeal_Recipient), FormControlEventType::Lookup)]
public static void TAMRebateDeal_Recipient_OnLookup(FormControl sender, FormControlEventArgs e)
{
    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        TAMRebateDeal rebateDeal = sender.formRun().dataSource(tableStr(TAMRebateDeal)).cursor();

        switch (rebateDeal.ModuleInventCustVend)
        {
            case ModuleInventCustVend::Cust:
                CustTable::lookupCustomer(sender);
                break;
            case ModuleInventCustVend::Vend:
                VendTable::lookupVendor(sender);
                break;
        }
        FormControlCancelableSuperEventArgs ce = e as FormControlCancelableSuperEventArgs;
        ce.CancelSuperCall();
    }
}

[FormControlEventHandler(formControlStr(TAMRebateDealNewDeal, TAMRebateDeal_RebateAgreementType), FormControlEventType::Lookup)]
public static void TAMRebateDeal_RebateAgreementType_OnLookup(FormControl sender, FormControlEventArgs e)
{
    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        TAMRebateDeal rebateDeal = sender.formRun().dataSource(tableStr(TAMRebateDeal)).cursor();
        TAMRebateDealGUPExtensionHelper::rebateAgreementLookupBasedOnCompany(sender, rebateDeal.RebateCompanyId);
        FormControlCancelableSuperEventArgs ce = e as FormControlCancelableSuperEventArgs;
        ce.CancelSuperCall();
    }
}

[FormControlEventHandler(formControlStr(TAMRebateDealNewDeal, TAMRebateDeal_RebateCompanyId), FormControlEventType::Modified)]
public static void TAMRebateDeal_RebateCompanyId_OnModified(FormControl sender, FormControlEventArgs e)
{
    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        TAMRebateDeal rebateDeal = sender.formRun().dataSource(tableStr(TAMRebateDeal)).cursor();
        rebateDeal.RebateAgreementType = '';
    }
}
